async function answerFrame(ws: WebSocket, validation: ValidationResult, store?: import('../../types/sessionStore.js').SessionStore): Promise<void> {
  if (!validation.valid) {
    log.warn('message', 'validation failed', {error: validation.error});
    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
    return;
  }

  const message = validation.data;
  if (message.type === 'ping') handlePing(ws, message.timestamp);
  else if (message.type === 'list_sessions') {
    if (!store || !store.listFor) {
      ws.send(JSON.stringify({type: 'session_list', sessions: []}));
      return;
    }
    const extWs = ws as import('./connectionHandler.js').ExtWebSocket;
    const userId = extWs.userId;
    try {
      const summaries = await store.listFor(userId, {limit: message.limit, before: message.before});
      const sessions = summaries.map(s => ({
        sessionId: s.sessionId,
        createdAt: s.createdAt.toISOString(),
        updatedAt: s.updatedAt.toISOString(),
        entryCount: s.entryCount,
      }));
      ws.send(JSON.stringify({type: 'session_list', sessions}));
    } catch (error) {
      log.error('ws', 'list_sessions failed', {userId, error: error instanceof Error ? error.message : String(error)});
      sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to fetch sessions');
    }
  }
}

